26	/// GitHub's download hosts: a repository's archives and releases, and
27	/// where GitHub redirects them. What is cached when nothing else is said.
28	pub const GITHUB: &[&str] = &[
29	    "github.com",
30	    "codeload.github.com",
31	    "objects.githubusercontent.com",
32	    "release-assets.githubusercontent.com",
33	];
