38	/// An S3 bucket (R2, S3, anything that speaks S3's API and signing).
39	pub struct BucketConfig {
40	    /// e.g. `https://<account id>.r2.cloudflarestorage.com`.
41	    pub endpoint: String,
42	    pub name: String,
43	    /// `auto` for R2.
44	    pub region: String,
