50	    pub bucket: BucketConfig,
51	    /// The hosts cached; a redirect to any other is refused.
52	    pub hosts: Vec<String>,
53	    /// Without one, nothing new is fetched at all.
54	    pub token: Option<String>,
55	    /// Where a download waits between upstream and the bucket.
56	    pub scratch: PathBuf,
57	    /// The largest file fetched.
58	    pub most_bytes: u64,
59	    /// In tests, the stand-in every host is served by, as
60	    /// `<origin>/<host>/<path>`; `https://<host>` otherwise.
61	    pub origin: Option<String>,
62	}
