64	pub struct Cache {
65	    /// Upstream: follows redirects, but only to the configured hosts.
66	    upstream: reqwest::Client,
67	    /// The bucket.
68	    http: reqwest::Client,
69	    bucket: Bucket,
70	    credentials: Credentials,
71	    hosts: Vec<String>,
72	    token: Option<String>,
73	    scratch: PathBuf,
74	    most_bytes: u64,
75	    /// Names each download's scratch file.
76	    downloads: AtomicU64,
77	    origin: Option<String>,
78	}
