80	impl Cache {
81	    pub fn new(config: Config) -> Result<Cache, String> {
82	        // reqwest is built without a crypto provider of its own, so rustls
83	        // has to be told which, once per process.
84	        let _ = rustls::crypto::ring::default_provider().install_default();
85	        let endpoint = config
86	            .bucket
87	            .endpoint
88	            .parse()
89	            .map_err(|e| format!("the bucket's endpoint {}: {e}", config.bucket.endpoint))?;
90	        let bucket = Bucket::new(
91	            endpoint,
92	            UrlStyle::Path,
93	            config.bucket.name,
94	            config.bucket.region,
95	        )
96	        .map_err(|e| format!("the bucket: {e}"))?;
97	        let hosts = config.hosts.clone();
98	        let stand_in = config.origin.clone();
99	        let redirects = reqwest::redirect::Policy::custom(move |attempt| {
100	            let allowed = attempt.url().host_str().is_some_and(|host| {
101	                hosts.iter().any(|h| h == host)
102	                    || stand_in
103	                        .as_deref()
104	                        .is_some_and(|o| o.contains(&format!("//{host}")))
105	            });
106	            if attempt.previous().len() > 5 {
107	                attempt.error("too many redirects")
108	            } else if allowed {
109	                attempt.follow()
110	            } else {
111	                attempt.error("a redirect away from the cached hosts")
112	            }
113	        });
114	        Ok(Cache {
115	            upstream: reqwest::Client::builder()
116	                .redirect(redirects)
117	                .user_agent(format!(
118	                    "releaseway/{}",
119	                    option_env!("RELEASEWAY_VERSION").unwrap_or("dev")
120	                ))
121	                .build()
122	                .map_err(|e| format!("an HTTP client: {e}"))?,
123	            http: reqwest::Client::new(),
124	            bucket,
125	            credentials: Credentials::new(
126	                config.bucket.access_key_id,
127	                config.bucket.secret_access_key,
128	            ),
129	            hosts: config.hosts,
130	            token: config.token.filter(|t| !t.is_empty()),
131	            scratch: config.scratch,
132	            most_bytes: config.most_bytes,
133	            downloads: AtomicU64::new(0),
134	            origin: config.origin,
135	        })
136	    }
137	
138	    /// Answers `GET <path>`: from the bucket, or from upstream by way of it.
139	    pub async fn serve(&self, path: &str, query: Option<&str>, headers: &HeaderMap) -> Response {
140	        let Some(named) = named(path, &self.hosts).filter(|_| query.is_none()) else {
141	            return (StatusCode::NOT_FOUND, "not something this caches\n").into_response();
142	        };
143	        match self.in_bucket(&named.key).await {
144	            Ok(Some(found)) => return found,
145	            Ok(None) => {}
146	            Err(e) => return failed("reading the bucket", &e),
147	        }
148	        if !self.authorized(headers) {
149	            return (
150	                StatusCode::UNAUTHORIZED,
151	                [(header::WWW_AUTHENTICATE, "Basic realm=\"releaseway\"")],
152	                "not cached yet, and only fetched with the token\n",
153	            )
154	                .into_response();
155	        }
156	        let url = match &self.origin {
157	            Some(origin) => format!("{origin}/{}/{}", named.host, named.rest),
158	            None => format!("https://{}/{}", named.host, named.rest),
159	        };
160	        match self.fetch(&url, &named.key).await {
161	            Ok(Fetched::Stored(bytes)) => {
162	                tracing::info!(key = %named.key, bytes, "cached");
163	            }
164	            Ok(Fetched::Answered(status)) => {
165	                return (status, "upstream did not have it\n").into_response();
166	            }
167	            Err(e) => return failed("caching", &e),
168	        }
169	        match self.in_bucket(&named.key).await {
170	            Ok(Some(found)) => found,
171	            Ok(None) => failed("caching", "the bucket did not keep it"),
172	            Err(e) => failed("reading the bucket", &e),
173	        }
174	    }
175	
176	    /// Whether `headers` carry the token: as a bearer token, or as the
177	    /// password of Basic auth, which is how Bazel, curl and most other
178	    /// tools send what `~/.netrc` has for a host, whatever the login.
179	    fn authorized(&self, headers: &HeaderMap) -> bool {
180	        let Some(token) = &self.token else {
181	            return false;
182	        };
183	        let Some(given) = headers
184	            .get(header::AUTHORIZATION)
185	            .and_then(|v| v.to_str().ok())
186	        else {
187	            return false;
188	        };
189	        let offered = if let Some(bearer) = given.strip_prefix("Bearer ") {
190	            bearer.to_string()
191	        } else if let Some(basic) = given.strip_prefix("Basic ") {
192	            let Ok(decoded) = base64::engine::general_purpose::STANDARD.decode(basic.trim()) else {
193	                return false;
194	            };
195	            let decoded = String::from_utf8_lossy(&decoded).into_owned();
196	            match decoded.split_once(':') {
197	                Some((_, password)) => password.to_string(),
198	                None => return false,
199	            }
200	        } else {
201	            return false;
202	        };
203	        same(offered.as_bytes(), token.as_bytes())
204	    }
205	
206	    /// The object at `key`, as the answer to the request for it; None when
207	    /// the bucket has no such object.
208	    async fn in_bucket(&self, key: &str) -> Result<Option<Response>, String> {
209	        let url = self
210	            .bucket
211	            .get_object(Some(&self.credentials), key)
212	            .sign(SIGNED_FOR);
213	        let found = self.http.get(url).send().await.map_err(|e| e.to_string())?;
214	        if found.status() == reqwest::StatusCode::NOT_FOUND {
215	            return Ok(None);
216	        }
217	        if !found.status().is_success() {
218	            return Err(format!("the bucket answered {}", found.status()));
219	        }
220	        let mut answer = Response::builder().status(StatusCode::OK);
221	        for name in [header::CONTENT_LENGTH, header::CONTENT_TYPE, header::ETAG] {
222	            if let Some(value) = found.headers().get(name.as_str())
223	                && let Ok(value) = HeaderValue::from_bytes(value.as_bytes())
224	            {
225	                answer = answer.header(name, value);
226	            }
227	        }
228	        answer
229	            .header(header::CACHE_CONTROL, "public, max-age=31536000, immutable")
230	            .body(Body::from_stream(found.bytes_stream()))
231	            .map(Some)
232	            .map_err(|e| e.to_string())
233	    }
234	
235	    /// Downloads `url` and puts it in the bucket as `key`, by way of a
236	    /// scratch file, so neither a large file nor a slow bucket is held in
237	    /// memory.
238	    async fn fetch(&self, url: &str, key: &str) -> Result<Fetched, String> {
239	        let mut download = self
240	            .upstream
241	            .get(url)
242	            .send()
243	            .await
244	            .map_err(|e| e.to_string())?;
245	        if !download.status().is_success() {
246	            // Upstream's own 404 is a 404 here; anything else is ours to say.
247	            let status = if download.status() == reqwest::StatusCode::NOT_FOUND {
248	                StatusCode::NOT_FOUND
249	            } else {
250	                StatusCode::BAD_GATEWAY
251	            };
252	            return Ok(Fetched::Answered(status));
253	        }
254	        let most = self.most_bytes;
255	        if download.content_length().is_some_and(|n| n > most) {
256	            return Err(format!("{url} is more than {most} bytes"));
257	        }
258	        tokio::fs::create_dir_all(&self.scratch)
259	            .await
260	            .map_err(|e| format!("making {}: {e}", self.scratch.display()))?;
261	        let n = self.downloads.fetch_add(1, Ordering::Relaxed);
262	        let scratch = self.scratch.join(format!("download-{n}"));
263	        let result = async {
264	            let mut file = tokio::fs::File::create(&scratch)
265	                .await
266	                .map_err(|e| format!("making {}: {e}", scratch.display()))?;
267	            let mut bytes = 0u64;
268	            while let Some(chunk) = download.chunk().await.map_err(|e| e.to_string())? {
269	                bytes += chunk.len() as u64;
270	                if bytes > most {
271	                    return Err(format!("{url} is more than {most} bytes"));
272	                }
273	                file.write_all(&chunk).await.map_err(|e| e.to_string())?;
274	            }
275	            file.flush().await.map_err(|e| e.to_string())?;
276	            drop(file);
277	            let put = self
278	                .bucket
279	                .put_object(Some(&self.credentials), key)
280	                .sign(SIGNED_FOR);
281	            let body = tokio::fs::File::open(&scratch)
282	                .await
283	                .map_err(|e| e.to_string())?;
284	            let stored = self
285	                .http
286	                .put(put)
287	                .header(reqwest::header::CONTENT_LENGTH, bytes)
288	                .body(body)
289	                .send()
290	                .await
291	                .map_err(|e| e.to_string())?;
292	            if !stored.status().is_success() {
293	                return Err(format!(
294	                    "the bucket answered {} to the upload",
295	                    stored.status()
296	                ));
297	            }
298	            Ok(Fetched::Stored(bytes))
299	        }
300	        .await;
301	        let _ = tokio::fs::remove_file(&scratch).await;
302	        result
303	    }
304	}
305	
306	enum Fetched {
307	    /// In the bucket now, this many bytes of it.
308	    Stored(u64),
309	    /// Upstream had nothing to give, and this is what to say instead.
310	    Answered(StatusCode),
311	}
312	
313	/// What a request path names: a cached host and a path on it, and the
314	/// object it is kept as in the bucket, which is the two together.
315	#[derive(Debug, PartialEq)]
316	pub struct Named {
317	    pub host: String,
318	    pub rest: String,
319	    pub key: String,
320	}
321	
322	/// `/<host>/<path>`, when the host is one of `hosts` and the path could
323	/// only ever name a file there: no empty, `.` or `..` segments, and nothing
324	/// but what a URL path has unencoded.
325	pub fn named(path: &str, hosts: &[String]) -> Option<Named> {
326	    let (host, rest) = path.strip_prefix('/')?.split_once('/')?;
327	    if !hosts.iter().any(|h| h == host) || rest.is_empty() {
328	        return None;
329	    }
330	    let tidy = rest
331	        .split('/')
332	        .all(|segment| !segment.is_empty() && segment != "." && segment != "..");
333	    let plain = rest
334	        .bytes()
335	        .all(|b| b.is_ascii_alphanumeric() || b"-._~/%+@=,".contains(&b));
336	    (tidy && plain).then(|| Named {
337	        host: host.to_string(),
338	        rest: rest.to_string(),
339	        key: format!("{host}/{rest}"),
340	    })
341	}
342	
343	/// Whether `a` and `b` are equal, taking as long whichever byte differs.
344	fn same(a: &[u8], b: &[u8]) -> bool {
345	    a.len() == b.len() && a.iter().zip(b).fold(0u8, |acc, (x, y)| acc | (x ^ y)) == 0
346	}
347	
348	fn failed(doing: &str, error: &str) -> Response {
349	    tracing::error!(error = %error, "{doing}");
350	    (StatusCode::BAD_GATEWAY, format!("{doing}: {error}\n")).into_response()
351	}
352	
353	#[cfg(test)]
354	mod tests {
355	    use super::*;
356	
357	    fn github() -> Vec<String> {
358	        GITHUB.iter().map(|h| h.to_string()).collect()
359	    }
360	
361	    #[test]
362	    fn only_the_configured_hosts_are_cached() {
363	        assert_eq!(
364	            named(
365	                "/github.com/bats-core/bats-core/archive/v1.10.0.tar.gz",
366	                &github()
367	            ),
368	            Some(Named {
369	                host: "github.com".into(),
370	                rest: "bats-core/bats-core/archive/v1.10.0.tar.gz".into(),
371	                key: "github.com/bats-core/bats-core/archive/v1.10.0.tar.gz".into(),
372	            })
373	        );
374	        assert!(
375	            named(
376	                "/github.com/k3s-io/k3s/releases/download/v1.33.4%2Bk3s1/k3s",
377	                &github()
378	            )
379	            .is_some()
380	        );
381	        for path in [
382	            "/example.com/a/b",
383	            "/github.com/",
384	            "/github.com",
385	            "/github.com/a/../b",
386	            "/github.com/a//b",
387	            "/github.com/a/b?x",
388	            "/github.com/a/b c",
389	            "github.com/a/b",
390	        ] {
391	            assert_eq!(named(path, &github()), None, "{path}");
392	        }
393	        assert!(named("/example.com/a/b", &["example.com".to_string()]).is_some());
394	    }
395	
396	    #[test]
397	    fn the_token_is_compared_whole() {
398	        assert!(same(b"abc", b"abc"));
399	        assert!(!same(b"abc", b"abd"));
400	        assert!(!same(b"abc", b"abcd"));
401	    }
402	}
